trigger_prototypes.description:
Alerta MSPClouds detectado.

Cliente: {#ALERT_CLIENT}
Tipo: {#ALERT_TYPE}
Detectado em: {#ALERT_CREATED}

parameters:
var data = JSON.parse(value);
var result = [];
if (Array.isArray(data) && data.length > 0) {
    data.forEach(function(alert) {
        result.push({
            "{#ALERT_CLIENT}": alert.client,
            "{#ALERT_TYPE}": alert.type,
            "{#ALERT_PRODUCT}": alert.product_keyword,
            "{#ALERT_CREATED}": alert.created_at
        });
    });
}
return JSON.stringify(result);

