trigger_prototypes.description:
O backup do cliente {#CLIENT_NAME} não teve sucesso há mais tempo que o tolerado.

Backupset: {#BACKUPSET_NAME}
Login: {#LOGIN_NAME}
Destino: {#DESTINATION}
Threshold configurado: {$MSPCLOUDS.BACKUP.MAX_AGE}

Clique na URL para ver o relatório detalhado.

O backup do cliente {#CLIENT_NAME} falhou.

Backupset: {#BACKUPSET_NAME}
Login: {#LOGIN_NAME}
Destino: {#DESTINATION}

Clique na URL da trigger para ver o relatório detalhado do backup.

parameters:
var data = JSON.parse(value);
var result = [];
if (data.clients && data.clients.length > 0) {
    data.clients.forEach(function(client) {
        if (client.backupsets && client.backupsets.length > 0) {
            client.backupsets.forEach(function(bs) {
                result.push({
                    "{#CLIENT_ID}": client.id,
                    "{#CLIENT_NAME}": client.name,
                    "{#BACKUPSET_ID}": bs.backup_set_id,
                    "{#BACKUPSET_NAME}": bs.backup_set_name,
                    "{#BACKUPSET_TYPE}": bs.backup_set_type,
                    "{#LOGIN_NAME}": bs.login_name,
                    "{#LOGIN_DESC}": bs.login_description,
                    "{#DESTINATION}": bs.destination_name
                });
            });
        }
    });
}
return JSON.stringify(result);
